<script setup lang="ts">
import SelectField from '../../components/SelectField.vue'
import { ref } from 'vue'
import { Plus, Trash2, Save } from '@lucide/vue'
import Modal from '../../components/Modal.vue'
import type { Source } from '../../app/types'
import { clone, state, saveConfiguration } from '../../app/state'
const props = defineProps<{ source?: Source }>(); const emit = defineEmits<{ close: [] }>()
function blank(): Source { return { id: '', name: '', type: 'rsync', enabled: true, dest: '', exclude: [], upstreams: {}, rsync: { preserve_links: true, preserve_times: true, preserve_permissions: true, preserve_hardlinks: true, delete: true, uid: null, gid: null }, reposync: { repo_id: '', releasever: '9', basearch: 'x86_64', architectures: ['x86_64','noarch'], download_metadata: true, newest_only: false, delete: true, gpgcheck: true, gpg_keys: [], module_hotfixes: false }, github_release: { repository: '', release_count: 0, asset_patterns: [] }, schedule: { enabled: false, cron: '0 2 * * *', overlap: 'skip' } } }
const draft = ref<Source>(props.source ? clone(props.source) : blank()); const upstreams = ref(Object.entries(draft.value.upstreams ?? {}).sort(([a],[b]) => Number(a.slice(3))-Number(b.slice(3))).map(([key,value]) => ({key,value}))); if (!upstreams.value.length) upstreams.value.push({key:'src1',value:''})
const exclusions = ref((draft.value.exclude ?? []).join('\n')); const patterns = ref((draft.value.github_release.asset_patterns ?? []).join('\n')); const keys = ref((draft.value.reposync.gpg_keys ?? []).join('\n')); const architectures = ref((draft.value.reposync.architectures ?? []).join(', ')); const error = ref(''); const busy = ref(false)
const flags = [{key:'preserve_links',label:'保留符号链接'},{key:'preserve_times',label:'保留修改时间'},{key:'preserve_permissions',label:'保留权限'},{key:'preserve_hardlinks',label:'保留硬链接'},{key:'delete',label:'删除上游已移除文件'}] as const
for (const flag of flags) draft.value.rsync[flag.key] ??= true
for (const flag of ['download_metadata','gpgcheck','delete'] as const) draft.value.reposync[flag] ??= true
function lines(value: string) { return value.split('\n').map(v=>v.trim()).filter(Boolean) }
function addUpstream() { const next = Math.max(...upstreams.value.map(v=>Number(v.key.slice(3))),0)+1; upstreams.value.push({key:`src${next}`,value:''}) }
function number(key: 'uid' | 'gid', event: Event) { const raw = (event.target as HTMLInputElement).value; draft.value.rsync[key] = raw === '' ? null : Number(raw) }
async function save() { if (!state.config) return; busy.value = true; error.value = ''; try { const source = clone(draft.value); source.exclude = source.type==='rsync' ? lines(exclusions.value) : []; source.upstreams = source.type==='github_release' ? {} : Object.fromEntries((source.type==='reposync'?upstreams.value.slice(0,1):upstreams.value).map(item=>[item.key,item.value.trim()])); source.github_release.asset_patterns = lines(patterns.value); source.reposync.gpg_keys = lines(keys.value); source.reposync.architectures = architectures.value.split(',').map(v=>v.trim()).filter(Boolean); const config = clone(state.config.config); const index = config.sources.findIndex(item=>item.id===props.source?.id); if (index>=0) config.sources[index]=source; else config.sources.push(source); await saveConfiguration(config); emit('close') } catch(e) { error.value = e instanceof Error?e.message:String(e) } finally { busy.value=false } }
</script>
<template><Modal :title="source?'编辑同步源':'新增同步源'" wide @close="emit('close')"><form class="source-form" @submit.prevent="save"><div class="form-grid"><label>源名称<input v-model="draft.name" required placeholder="例如 RockyLinux 9"/></label><label>唯一标识<input v-model="draft.id" required :disabled="!!source" pattern="[A-Za-z0-9][A-Za-z0-9._-]*" placeholder="rockylinux-9"/></label><label>同步方式<SelectField v-model="draft.type" aria-label="同步方式" :options="[{ value: 'rsync', label: 'rsync' }, { value: 'reposync', label: 'DNF reposync' }, { value: 'github_release', label: 'GitHub Release' }] satisfies { value: Source['type']; label: string }[]" /></label><label>目的目录 · dest<input v-model="draft.dest" required placeholder="rockylinux/9"/><small>镜像地址：/{{draft.dest||'dest'}}/</small></label></div><section class="form-section" v-if="draft.type!=='github_release'"><h3>同步来源<span>按数字顺序尝试，切换不重置任务预算</span></h3><div class="upstream-row" v-for="(upstream,index) in upstreams" :key="upstream.key" v-show="draft.type==='rsync'||index===0"><span>{{upstream.key}}</span><input v-model="upstream.value" required :placeholder="draft.type==='rsync'?'rsync://mirror.example/repo/':'https://nginx.org/packages/centos/9/x86_64/'"/><button v-if="index>0" type="button" class="icon-button" aria-label="删除备用来源" @click="upstreams.splice(index,1)"><Trash2 :size="16"/></button></div><button v-if="draft.type==='rsync'" type="button" class="button subtle" @click="addUpstream"><Plus :size="15"/>添加备用来源</button></section><section v-if="draft.type==='rsync'" class="form-section"><h3>rsync 选项</h3><label>排除规则 · exclude<textarea v-model="exclusions" rows="3" placeholder="一行一条，例如 isos/**"/></label><div class="check-grid"><label v-for="flag in flags" :key="flag.key" class="check"><input v-model="draft.rsync[flag.key]" type="checkbox"/>{{flag.label}}</label></div><div class="form-grid"><label>UID · 可选<input type="number" min="0" :value="draft.rsync.uid??''" @input="number('uid',$event)" placeholder="留空使用程序身份；0 表示 root"/></label><label>GID · 可选<input type="number" min="0" :value="draft.rsync.gid??''" @input="number('gid',$event)" placeholder="留空不做映射"/></label></div><small>指定 UID 通常需要接收端具有 root 权限；程序不会自动提权。</small></section><section v-if="draft.type==='github_release'" class="form-section"><h3>Release 附件</h3><div class="form-grid"><label>GitHub 仓库<input v-model="draft.github_release.repository" required placeholder="OpenListTeam/OpenList"/></label><label>同步最近 N 个 Release<input v-model.number="draft.github_release.release_count" type="number" min="0" max="100"/><small>0 表示继承系统设置；按发布时间从新到旧。</small></label></div><label>附件 glob<textarea v-model="patterns" rows="3" placeholder="一行一条，例如 *linux*amd64*"/></label><small>只下载 Release assets，自动生成的源码归档不参与同步。</small></section><section v-if="draft.type==='reposync'" class="form-section"><h3>DNF 仓库选项</h3><div class="form-grid"><label>仓库 ID<input v-model="draft.reposync.repo_id" required/></label><label>发行版版本<input v-model="draft.reposync.releasever" required/></label><label>basearch<input v-model="draft.reposync.basearch" required/></label><label>架构范围<input v-model="architectures" placeholder="x86_64, noarch"/></label></div><label>GPG 公钥地址<textarea v-model="keys" rows="2" placeholder="一行一个 HTTPS 地址"/></label><div class="check-grid"><label class="check"><input v-model="draft.reposync.download_metadata" type="checkbox"/>下载 metadata</label><label class="check"><input v-model="draft.reposync.gpgcheck" type="checkbox"/>检查包签名</label><label class="check"><input v-model="draft.reposync.delete" type="checkbox"/>清理上游已删除 RPM</label><label class="check"><input v-model="draft.reposync.module_hotfixes" type="checkbox"/>module_hotfixes</label></div></section><section class="form-section"><h3>运行计划</h3><div class="form-grid"><label>cron 表达式<input v-model="draft.schedule.cron" placeholder="0 2 * * *"/><small>五字段，使用程序启动时区；任务重叠默认跳过。</small></label><div class="check-stack"><label class="check"><input v-model="draft.schedule.enabled" type="checkbox"/>启用自动计划</label><label class="check"><input v-model="draft.enabled" type="checkbox"/>启用此同步源</label></div></div></section><div v-if="error" class="alert error" role="alert">{{error}}</div><footer class="modal-actions"><button type="button" class="button" @click="emit('close')">取消</button><button class="button primary" :disabled="busy"><Save :size="16"/>{{busy?'正在保存…':'保存并写回 YAML'}}</button></footer></form></Modal></template>
